INSERT INTO evidence_notes(note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES
('N056-01','CN0309','S056-01','设施与设备','§3.4.2 pp75–80','2019杭州永邦环境科技设计扩建；2020年2月调试完毕并验收。400t/d、100t/d子系统；酸/H2O2、NaOH/助凝剂、末端PAC/PAM，板框污泥脱水；1497m³事故池非日处理量；在线pH、流量、COD、氨氮。固废渗滤液p76称入污水站、§3.4.4 p84称危废处置，保留异文。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N056-02','CN0309','S056-01','扩容设计','§3.4.2.3 pp80–83 图3.4-5','北侧99.29亩、8860吨项目2021年6月批复，2024报告尚未开始建设。拟1000t/d取代400t/d生化；两配水池轮换，初沉至终沉两套并联，末端预留过滤用地；监护回流；污泥耙式烘干。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N056-03','CN0309','S056-02','投资与边界','p2–5','七产品技改总投资780万元、环保150万元；高溴离子水中和蒸发后入厂站，近期和远期园区接管不同；批复总排放量8485t/a；非全厂实际污水成本。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N056-04','CN0309','S056-03','产能与膜边界','2025年报产能表及研发计划','仙居13906吨、江西16810.42吨，利用率分别83.14%、65.16%；集团2767吨技改部分投产，未将其再加到基地总量；离子膜有机电解技术为产品工艺研发，非污水膜。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N056-05','CN0309','S056-04','历史环保成本','招股说明书1-1-185','集团综合环保费2021/22/23/2024H1为565.85/785.57/451.64/161.04万元；环保设施设备投入2470.15/405.28/213.20/19.03万元。均为集团混合环保口径，非厂区污水单价、不得分摊。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N056-06','CN0309','S056-05','2025运行披露','污废防治章节','ESG报告复述400t/d及高浓100t/d、三效/臭氧化学沉淀、铁碳高级氧化及生化组合。组织范围集团；按与仙居环评一致的设施归属，仅作为企业自述佐证，不证明2026在运或新站已建。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N056-07','CN0310','S056-04','新址与污水站','1-1-52、1-1-185及历史迁址说明','全资子公司、茅坪产业园、2021年6月试产后7月底全部转移；420m³/d站正常运行是招股报告期企业披露，未列单元及末端。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N056-08','CN0310','S056-03','产能口径','2025年报产能表','江西基地16810.42吨设计、利用率65.16%，不等于专用催化剂产量。','WEB_COMPANY','WEB_TEXT','2026-11-28');
