INSERT INTO membrane_retrofits(assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES
('A056-01','R056-01','CN0309','old-central-wwtp','screening',1,'回用/减盐条件初筛','末端混凝后试UF+RO；先小试评估溴/氯盐和有机物；产水拟冷却补水','conditional','浓水合规去向必须闭合；不得直将高浓季铵废液送RO','§3.4.2.3逐项实际站设备/工序为物化和生化沉淀；仅该历史综合站，无膜，不推全厂','INFERRED；仅候选，非在建或运行','现行流量、溴/盐组成、TOC、温度、硬度、浓水接受和成本','连续取样、毒性/膜相容性、UF/RO污染与CIP、浓水物料衡算、全生命周期费用','现行纳管、优化分质与蒸发回收',2,1,NULL,NULL,1,NULL,'进水高COD/TN且出水氯离子约1.2g/L，feed=2；已有物化生化但需膜前处理=1；污染验证=1；其它不确定，难度unknown','2026-11-28'),
('A056-02','R056-02','CN0309','planned-central-wwtp','screening',1,'回用/减盐条件初筛','若扩建尚未实施，预留深度过滤接口，比较UF+RO回用与仅达标纳管；先分流高盐','conditional','新站建设状态及浓水去向未核','图3.4-5与pp81–83方案未列污水膜，预留过滤不等于膜','INFERRED；仅候选，非在建或运行','新站状态、回用要求、水量、盐种、经济性','确认项目进度，分股采样、预处理小试及浓水平衡','两段A/O及现行分质蒸发',2,1,NULL,NULL,NULL,NULL,'设计盐≤6000mg/L、COD≤4500，feed=2；已有设计预处理需验证=1；其余未知','2026-11-28'),
('A056-03','R056-03','CN0310','production-wwtp','screening',1,'回用/减盐条件初筛','先取得环评、许可和站内图，再筛低盐出水回用或高盐分质；不能推荐具体膜设备','unknown','内部工艺和合法浓水出口未知','招股1-1-185仅列站能力和污染物，无法判断膜','INFERRED；仅候选，非在建或运行','现行站清单、流量、水质、回用、成本','查2025季铵鏻技改环评受理、验收和排污许可；现场采样后再做膜小试','保持既有站，先核源头分质',NULL,NULL,NULL,NULL,NULL,NULL,'无充分数据，六维不评分','2026-11-28');
